local function classifyError(err)
  local text = tostring(err or ""):lower()
  if text:find("response_read_failed",1,true) then return "BRW-002" end
  if text:find("http api disabled", 1, true) then return "BRW-001" end
  if text:find("permission", 1, true) or text:find("blocked", 1, true) then return "BRW-003" end
  if text:find("redirect", 1, true) then return "BRW-004" end
  if text:find("empty url", 1, true) or text:find("invalid", 1, true) then return "BRW-005" end
  if text:find("cache", 1, true) then return "BRW-007" end
  if text:find("download", 1, true) or text:find("write", 1, true) then return "BRW-008" end
  if text:find("request failed", 1, true) or text:find("ssl", 1, true) or text:find("dns", 1, true) or text:find("timed", 1, true) or text:find("closed", 1, true) then return "BRW-002" end
  return "BRW-000"
end

function M.run(ctx)
  ensureDirs()
  local settings = config.load(SETTINGS, defaultSettings())
  if type(settings)~="table" then settings=defaultSettings() end
  for k,v in pairs(defaultSettings()) do if type(settings[k])~=type(v) then settings[k]=v end end
  settings.maxRedirects=math.max(0,math.min(5,math.floor(settings.maxRedirects)))
  local function list(value,fields,limit)
    local out={}
    if type(value)=="table" then for i=1,math.min(#value,limit) do
      local row=value[i] local valid=type(row)=="table"
      if valid then for _,key in ipairs(fields) do if type(row[key])~="string" then valid=false end end end
      if valid then out[#out+1]=row end
    end end return out
  end

  local app = {
    tabs = { newTab((ctx.args and ctx.args.url and ctx.args.url ~= "") and ctx.args.url or settings.home) },
    active = 1,
    address = "",
    focusAddress = false,
    status = "Ready",
    keyboard = {},
    history = loadData(HISTORY, {}),
    bookmarks = loadData(BOOKMARKS, {
      { title = "GitHub", url = "https://github.com" },
      { title = "CraftTube", url = "mint://crafttube?q=" },
      { title = "YouTube", url = "https://youtube.com" },
      { title = "Docs", url = "https://tweaked.cc" },
    }),
    downloads = loadData(DOWNLOADS, {}),
    linkBoxes = {},
  }
  app.history=list(app.history,{"title","url"},80)
  app.bookmarks=list(app.bookmarks,{"title","url"},64)
  app.downloads=list(app.downloads,{"filename","status"},80)
  local worker
  local function enqueue(action,value)
    local ok,err=worker:submit({action=action,value=value,index=app.active})
    app.status=ok and "Loading..." or tostring(err)
  end

  local function tab() return app.tabs[app.active] end

  local function saveAll()
    saveData(HISTORY, app.history)
    saveData(BOOKMARKS, app.bookmarks)
    saveData(DOWNLOADS, app.downloads)
    config.save(SETTINGS, settings)
  end

  local function errorPage(code, detail, url)
    code = code or classifyError(detail)
    local def = ERROR_DEFS[code] or ERROR_DEFS["BRW-000"]
    local lines = {
      "# " .. code .. " - " .. def.title,
      "",
      "What happened:",
      tostring(detail or def.title),
      "",
      "Meaning:",
      def.hint,
      "",
      "URL:",
      tostring(url or tab().url or "-"),
      "",
      "[1] Reload",
      "[2] Home",
      "[3] Open Network Settings",
    }
    return {
      title = code,
      lines = lines,
      links = {
        { index = 1, text = "Reload", url = tostring(url or tab().url or settings.home) },
        { index = 2, text = "Home", url = settings.home },
        { index = 3, text = "Settings", url = "mint://settings?network" },
      },
      status = 0,
      error = true,
      errorCode = code,
    }
  end

  local function homePage()
    local lines = {
      "# MintCraft Browser",
      "",
      "Search or enter address in the bar above.",
      "",
      "Quick links:",
    }
    local links = {}
    for i, b in ipairs(app.bookmarks) do
      table.insert(lines, "[" .. i .. "] " .. b.title .. "  " .. b.url)
      table.insert(links, { index = i, text = b.title, url = b.url })
    end
    table.insert(lines, "")
    table.insert(lines, "Recent:")
    for i = 1, math.min(5, #app.history) do
      local idx = #links + 1
      table.insert(lines, "[" .. idx .. "] " .. app.history[i].title .. "  " .. app.history[i].url)
      table.insert(links, { index = idx, text = app.history[i].title, url = app.history[i].url })
    end
    table.insert(lines, "")
    table.insert(lines, "Downloads:")
    for i = 1, math.min(3, #app.downloads) do table.insert(lines, "- " .. app.downloads[i].filename .. "  " .. app.downloads[i].status) end
    return { title = "New Tab", lines = lines, links = links, status = 200 }
  end

  local function addHistory(t, page)
    if t.private or not page then return end
    table.insert(app.history, 1, { url = t.url, title = page.title or t.url, timestamp = now(), status = page.status or 0 })
    while #app.history > 80 do table.remove(app.history) end
    saveData(HISTORY, app.history)
  end

  local function headersFor(url, previous)
    return {
      ["User-Agent"] = settings.userAgent,
      ["Accept"] = "text/html,application/json,text/plain,*/*",
      ["Accept-Language"] = "fr-FR,fr;q=0.9,en;q=0.8",
      ["Referer"] = previous or "",
    }
  end

  local function openCraftTube(query)
    query = tostring(query or "")
    if query == "" then query = youtubeQuery(tab().url) end
    if query == "" and app.address ~= "" then query = app.address end
    local ok, err = ctx.apps.launch("crafttube", { query = query })
    if ok then
      app.status = query ~= "" and ("CraftTube search: " .. query) or "CraftTube opened"
    else
      app.status = tostring(err)
    end
  end

  local function loadUrl(url, addToHistory,target,bypass)
    local t = target or tab()
    url = normalizeAddress(url, settings.search)
    if url:match("^mint://crafttube") then
      local query = queryParam(url, "q")
      t.url = url
      t.title = "CraftTube"
      t.page = {
        title = "CraftTube",
        lines = {
          "# CraftTube",
          "",
          "YouTube runs inside MintCraft Browser through CraftTube.",
          "Search and audio playback use the configured CraftTube proxies.",
          "",
          "[1] Open CraftTube",
        },
        links = { { index = 1, text = "Open CraftTube", url = url } },
        status = 200,
      }
      openCraftTube(query)
      return
    end
    if isYouTube(url) then
      t.url = url
      t.title = "YouTube"
      t.page = {
        title = "BRW-006",
        lines = {
          "# BRW-006 - YouTube routed",
          "",
          ERROR_DEFS["BRW-006"].hint,
          "",
          "Reason:",
          "YouTube requires JavaScript and media codecs that CC:Tweaked does not provide.",
          "",
          "[1] Open in CraftTube",
        },
        links = { { index = 1, text = "Open in CraftTube", url = "mint://crafttube?q=" .. youtubeQuery(url) } },
        status = 200,
      }
      openCraftTube(youtubeQuery(url))
      return
    end
    if url == "mint://home" then
      t.url = url
      t.page = homePage()
      t.title = t.page.title
      return
    end
    if url == "mint://history" then
      local lines = { "# History", "" }
      for i, h in ipairs(app.history) do table.insert(lines, "[" .. i .. "] " .. h.title .. "  " .. h.url) end
      t.url = url
      t.page = { title = "History", lines = lines, links = {}, status = 200 }
      t.title = "History"
      return
    end

    local allowed, denied = ctx.security.require("network.http", url)
    if not allowed then
      t.page = errorPage("BRW-003", denied, url)
      t.title = t.page.title
      app.status = "BRW-003 " .. tostring(denied)
      return
    end

    local previous = t.url
    t.url=url
    local current = url
    local response, err
    for redirects = 0, settings.maxRedirects do
      app.status = "Loading " .. current
      local cachePath = CACHE .. "/" .. cacheKey(current) .. ".html"
      local metaPath=cachePath..".json"
      local cached
      if settings.cache and not t.private and not bypass and fs.exists(cachePath) and fs.getSize(cachePath)<=524288 then
        local meta=loadData(metaPath,{})
        if type(meta)=="table" and meta.url==current and type(meta.headers)=="table" and
          type(meta.expires)=="number" and not header(meta.headers,"vary") then
          local body=readFile(cachePath)
          if body then cached={url=current,code=200,body=body,headers=meta.headers,size=#body,expires=meta.expires} end
        end
      end
      local requestHeaders=headersFor(current,previous)
      if bypass then requestHeaders["Cache-Control"]="no-cache" end
      local allowedHop,deniedHop=ctx.security.require("network.http",current)
      if not allowedHop then response=nil err=deniedHop
      elseif cached and cacheTime()>0 and cached.expires>cacheTime() then
        response=cached
      else
        if cached then
          requestHeaders["If-None-Match"]=header(cached.headers,"etag")
          requestHeaders["If-Modified-Since"]=header(cached.headers,"last-modified")
        end
        response, err = httpClient.get(current, { headers=requestHeaders,redirect=false,timeout=10,maxBytes=524288,allowStatus={[304]=true} })
        if response and response.code==304 then
          if cached then
            for key,value in pairs(response.headers or {}) do
              for old in pairs(cached.headers) do if old:lower()==key:lower() then cached.headers[old]=nil end end
              cached.headers[key]=value
            end
            response=cached
          else response=nil err="REQUEST_FAILED: unexpected 304 without cached body" end
        end
        if settings.cache and not t.private and response and response.code==200 then
          local ttl=cachePolicy(response.headers)
          if ttl and not header(response.headers,"vary") then
            -- Publish metadata last; URL matching also prevents truncated-key collisions.
            if fs.exists(metaPath) then fs.delete(metaPath) end
            if writeFile(cachePath,response.body) then saveData(metaPath,{url=current,headers=response.headers,expires=cacheTime()+ttl}) end
          else
            if fs.exists(metaPath) then fs.delete(metaPath) end
            if fs.exists(cachePath) then fs.delete(cachePath) end
          end
        end
      end
      if not response then
        local code = classifyError(err)
        t.page = errorPage(code, tostring(err), current)
        t.title = t.page.title
        app.status = code .. " " .. tostring(err)
        log.warn("browser", code .. " " .. tostring(err) .. " url=" .. tostring(current))
        return
      end
      local location = response.headers and (response.headers.Location or response.headers.location)
      if REDIRECTS[response.code] and location then
        current = resolveUrl(current, location)
      else
        break
      end
      if redirects == settings.maxRedirects then
        t.page = errorPage("BRW-004", "Redirect limit reached", current)
        t.title = t.page.title
        app.status = "BRW-004 redirect limit"
        return
      end
    end

    if #response.body>524288 then
      t.page=errorPage("BRW-000","Page exceeds the 512 KiB reader limit",current) t.title=t.page.title
      app.status="Page too large" return
    end
    local page = parseHtml(response.body, response.url or current, app.lastW or 60)
    page.status = response.code
    t.url = response.url or current
    t.page = page
    t.title = page.title
    t.scroll = 1
    app.status = tostring(response.code) .. " " .. tostring(response.size) .. " bytes"
    if addToHistory ~= false then
      while #t.history > t.historyIndex do table.remove(t.history) end
      table.insert(t.history, t.url)
      t.historyIndex = #t.history
      addHistory(t, page)
    end
  end

  local function submitAddress()
    enqueue("load",{url=app.address ~= "" and app.address or tab().url,history=true})
    app.focusAddress = false
  end

  local function goHistory(delta,target)
    local t = target or tab()
    local nextIndex = t.historyIndex + delta
    if nextIndex >= 1 and nextIndex <= #t.history then
      t.historyIndex = nextIndex
      loadUrl(t.history[t.historyIndex], false,t)
    end
  end

  local function addBookmark()
    local t = tab()
    table.insert(app.bookmarks, { title = t.title or t.url, url = t.url, folder = "Bar", createdAt = now() })
    saveData(BOOKMARKS, app.bookmarks)
    app.status = "Bookmark added"
  end

  local function download(url,target)
    url = url or (target or tab()).url
    local allowed, denied = ctx.security.require("network.http", url)
    if not allowed then app.status = "BRW-003 " .. tostring(denied) return end
    local response, err = httpClient.get(url, { headers = headersFor(url, tab().url),binary=true,timeout=60,maxBytes=8388608 })
    if not response then app.status = classifyError(err) .. " " .. tostring(err) return end
    local filename = filenameFromUrl(url)
    local path = fs.combine(settings.downloadDir, filename)
    if not writeFile(path, response.body) then app.status="BRW-008 Cannot save download" return end
    table.insert(app.downloads, 1, { url = url, filename = filename, path = path, status = "done", received = response.size, startedAt = now() })
    saveData(DOWNLOADS, app.downloads)
    app.status = "Downloaded " .. filename
  end

  local function openLink(link)
    if not link then return end
    if tostring(link.url):match("^mint://crafttube") then
      openCraftTube(queryParam(link.url, "q"))
    elseif tostring(link.url):match("^mint://settings") then
      ctx.apps.launch("settings")
    else
      enqueue("load",{url=link.url,history=true,bypass=link.text=="Reload"})
    end
  end

  app.keyboard.onText = function(ch) app.address = app.address .. ch end
  app.keyboard.onBackspace = function() app.address = app.address:sub(1, -2) end
  app.keyboard.onEnter = submitAddress

  function app:draw(w, h)
    self.lastW = w
    local t = tab()
    self.linkBoxes = {}
    for _,item in ipairs(self.tabs) do item.tabX=nil end
    for _,b in ipairs(self.bookmarks) do b.x=nil end
    renderer.fill(1, 1, w, 1, colors.gray)
    local x = 1
    for i, item in ipairs(self.tabs) do
      local label = (i == self.active and "[" or " ") .. renderer.crop(item.title or "Tab", 10):gsub("%s+$", "") .. (i == self.active and "]" or " ")
      renderer.writeAt(x, 1, renderer.crop(label, math.min(12, w - x + 1)), colors.white, i == self.active and colors.blue or colors.gray)
      item.tabX, item.tabW = x, math.min(12, #label)
      x = x + item.tabW + 1
      if x > w - 3 then break end
    end
    renderer.writeAt(math.max(1, w - 2), 1, "+", colors.black, colors.lime)

    renderer.fill(1, 2, w, 1, colors.lightGray)
    renderer.writeAt(1, 2, "<", colors.black, colors.lightGray)
    renderer.writeAt(3, 2, ">", colors.black, colors.lightGray)
    renderer.writeAt(5, 2, "R", colors.black, colors.lightGray)
    renderer.writeAt(7, 2, "H", colors.black, colors.lightGray)
    renderer.writeAt(9, 2, "*", colors.black, colors.lightGray)
    renderer.writeAt(11, 2, "D", colors.black, colors.lightGray)
    renderer.writeAt(13, 2, "YT", colors.white, colors.red)
    local addr = self.focusAddress and self.address or t.url
    renderer.writeAt(16, 2, renderer.crop(addr, math.max(1, w - 15)), colors.black, colors.white)

    local y = 3
    if settings.showBookmarks then
      renderer.fill(1, y, w, 1, colors.gray)
      local bx = 1
      for i, b in ipairs(self.bookmarks) do
        local label = renderer.crop(b.title, 10):gsub("%s+$", "")
        renderer.writeAt(bx, y, "[" .. label .. "]", colors.white, colors.gray)
        b.x, b.y, b.w = bx, y, #label + 2
        bx = bx + b.w + 1
        if bx > w - 8 then break end
      end
      y = y + 1
    end

    local page = t.page or homePage()
    local kbH = self.focusAddress and keyboard.height() or 0
    local pageH = math.max(1, h - y - 1 - kbH)
    for i = 1, pageH do
      local lineIndex = t.scroll + i - 1
      local line = page.lines[lineIndex] or ""
      local fg = line:match("^#") and colors.blue or colors.black
      if line:match("%[%d+%]") then fg = colors.blue end
      renderer.writeAt(1, y + i - 1, renderer.crop(line, w), fg, colors.lightGray)
      for _, link in ipairs(page.links or {}) do
        if line:find("%[" .. tostring(link.index) .. "%]", 1, false) then
          table.insert(self.linkBoxes, { x = 1, y = y + i - 1, w = w, link = link })
        end
      end
    end
    renderer.writeAt(1, h - kbH, renderer.crop("Status: " .. self.status, w), colors.white, colors.gray)
    if self.focusAddress then
      self.keyboard.x = 1
      self.keyboard.y = math.max(1,h - kbH + 1)
      self.keyboard.hint = "Address/Search"
      keyboard.draw(1, self.keyboard.y, w, self.keyboard)
    end
  end

  function app:handle(event)
    local t = tab()
    if event.name == "mouse_scroll" then
      t.scroll = math.max(1, t.scroll + event.args[1])
      return true
    elseif event.name == "char" and self.focusAddress then
      self.address = self.address .. event.args[1]
      return true
    elseif event.name == "key" and self.focusAddress then
      local key = event.args[1]
      if key == keys.backspace then self.address = self.address:sub(1, -2) return true end
      if key == keys.enter then submitAddress() return true end
    elseif event.name == "mouse_click" then
      local _, x, y = table.unpack(event.args)
      if self.focusAddress and event.monitorTouch and keyboard.handle(event, self.keyboard) then return true end
      if y == 1 then
        if x >= self.lastW - 2 then
          if #self.tabs>=16 then self.status="Tab limit reached" return true end
          table.insert(self.tabs,newTab(settings.home)) self.active=#self.tabs enqueue("load",{url=settings.home,history=false}) return true
        end
        for i, item in ipairs(self.tabs) do
          if item.tabX and x >= item.tabX and x < item.tabX + item.tabW then self.active = i return true end
        end
      elseif y == 2 then
        if x == 1 then enqueue("history",-1) return true end
        if x == 3 then enqueue("history",1) return true end
        if x == 5 then enqueue("load",{url=t.url,history=false,bypass=true}) return true end
        if x == 7 then enqueue("load",{url=settings.home,history=true}) return true end
        if x == 9 then addBookmark() return true end
        if x == 11 then enqueue("download",t.url) return true end
        if x == 13 or x == 14 then openCraftTube(youtubeQuery(t.url)) return true end
        if x >= 16 then self.focusAddress = true self.address = t.url return true end
      elseif settings.showBookmarks and y == 3 then
        for _, b in ipairs(self.bookmarks) do
          if b.x and x >= b.x and x < b.x + b.w then enqueue("load",{url=b.url,history=true}) return true end
        end
      end
      for _, box in ipairs(self.linkBoxes or {}) do
        if y == box.y and x >= box.x and x < box.x + box.w then openLink(box.link) return true end
      end
    end
    return false
  end

  local sw, sh = term.getSize()
  local win = ctx.windowManager:create({ title = "Browser", w = math.min(82, sw - 4), h = math.min(26, sh - 3), x = 5, y = 3, app = app })
  worker=appWorker.new(ctx,"Browser requests",function(request)
    local target=app.tabs[request.index]
    if request.action=="load" then loadUrl(request.value.url,request.value.history,target,request.value.bypass)
    elseif request.action=="history" then goHistory(request.value,target)
    elseif request.action=="download" then download(request.value,target) end
  end,function(request,ok,err)
    if not ok then
      local target=app.tabs[request.index]
      target.page=errorPage(classifyError(err),tostring(err),target.url) target.title=target.page.title
      target.loading=false app.status=tostring(err) pcall(log.warn,"browser",app.status)
    elseif app.status=="Loading..." then app.status="Ready" end
  end,70)
  enqueue("load",{url=tab().url,history=false})
  while not win.closed do ctx.pullEvent() end
end

return M
]=],
  ["apps/combat/app.cfg"] = [=[
{
  id = "combat",
  name = "Combat",
  version = "0.18.15",
  main = "apps.combat.main",
  permissions = { "combat.read", "combat.aim", "combat.fire", "combat.configure", "peripheral.probe" },
}
]=],
  ["apps/combat/main.lua"] = [=[
local renderer=require("system.gui.renderer")
local ui=require("system.gui.components")
local menus=require("system.gui.action_menu")
local forms=require("system.gui.form")
local addon=require("system.libraries.addon")
local geometry=require("system.navigation.geometry")
local instruments=require("system.navigation.instruments")
local radarSetup=require("system.navigation.radar_setup")
local combat=require("system.services.combatd")
local radarNet=require("system.services.radarnetd")
local filter=require("system.navigation.radar_filter")
local M={}
local function find(rows,id) if id==nil then return nil end for _,row in ipairs(rows or {}) do if row.id==id or row.name==id then return row end end end
local function fmt(value) return addon.finite(value) and string.format("%.1f",value) or "unavailable" end
function M.run(ctx)
  local actor={pid=ctx.pid}
  local app={page="radar",tabState={},barState={},filterState={},pages=menus.new(),commands=menus.new(),categories=menus.new(),filters={},form=forms.new(),scroll=1,snapshot={},view={zoom=1,yaw=30,pitch=45},message="Semi-auto; manual fire confirmation",configKind="radar",tracking=false}
  local tabs={{id="radar",label="Radar"},{id="three",label="3D"},{id="targets",label="Targets"},{id="cannons",label="Cannons"},{id="fire",label="Fire"},{id="probe",label="Probe"},{id="config",label="Config"}}
  local cfg=combat.configuration()
  tabs[#tabs+1]={id="network",label="Network"}
  local win,timer,trackTimer
  local function refresh()
    local status=combat.status()
    if not app.snapshot.radars or app.snapshot.revision~=status.revision then app.snapshot=combat.snapshot() end
    if app.setup then app.setup:update(app.snapshot) end
    for _,target in ipairs(app.snapshot.targets or {}) do target.stale=target.pending or not target.freshnessKnown or os.clock()-target.timestamp>5 end
    if not find(app.snapshot.radars,app.radarId) then app.radarId=app.snapshot.radars[1] and app.snapshot.radars[1].id app.canvas=nil end
    if app.targetId and not find(app.snapshot.targets,app.targetId) then app.targetId=nil app.tracking=false app.confirm=nil app.solution=nil end
    if not app.cannonId and app.snapshot.cannons[1] then app.cannonId=app.snapshot.cannons[1].id end
  end
  local function report(ok,message) app.message=ok and (type(message)=="number" and "Queued #"..message or message or "Done") or tostring(message or "Refused") end
  local function confirm(title,callback) app.confirm={title=title,callback=callback} end
  local function selectTarget(id) app.targetId=filter.select(app.targetId,id) app.confirm=nil app.tracking=false app.solution=nil app.canvas=nil end
  local function solve()
    local solution,err=combat.solution(app.cannonId,app.targetId)
    app.solution=solution app.message=err or "Estimated vacuum trajectory (no drag)"
  end
  local function configObject()
    if app.configKind=="alias" then return app.alias or {value=""} end
    local section=app.configKind=="radar" and "radars" or "profiles"
    local id=app.configKind=="radar" and app.radarId or app.cannonId
    if not id then return end
    if not cfg[section][id] then
      local radar=find(app.snapshot.radars,id)
      cfg[section][id]=app.configKind=="radar" and {frame=radar and radar.frame=="world" and "world" or "unknown",headingFrame="world",headingSign=1,headingOffset=0,headingValidated=false} or {frame="unknown",headingFrame="world",yawSign=1,pitchSign=1,yawOffset=0,pitchOffset=0,validated=false}
    end
    return cfg[section][id]
  end
  local function fields()
    if app.configKind=="network" then
      local object=app.networkConfig
      local rows={}
      for _,entry in ipairs({{"group","World/dimension group","string"},{"sharedKey","Shared key (16+ chars)","secret"},{"allowInsecure","Allow unauthenticated Rednet","boolean"},{"x","Zone centre X","number"},{"y","Zone centre Y","number"},{"z","Zone centre Z","number"},{"radius","Zone radius m","number"},{"alerts","Perimeter alerts","boolean"}}) do
        rows[#rows+1]=forms.field(object,entry[1],entry[2],entry[3])
      end return rows
    end
    local object=configObject() local rows={}
    if not object then return rows end
    local function field(key,label,kind,options) rows[#rows+1]=forms.field(object,key,label,kind,options) end
    if app.configKind=="alias" then field("value","Local alias","string") return rows end
    field("frame","Position frame",nil,{"unknown","world","body"})
    field("headingFrame","Mount heading frame",nil,{"world","body"})
    if app.configKind=="radar" then
      field("apiProfile","Radar API profile",nil,{"auto","4.x","5.0-EA","bridge"})
      field("positionMode","Position source",nil,{"api","manual"})
      field("positionX","Radar position X","number")
      field("positionY","Radar position Y","number")
      field("positionZ","Radar position Z","number")
      field("headingSign","Rotation sign","number") field("headingOffset","Rotation offset deg","number")
      field("fov","Calibrated FOV deg","number") field("heading","Fixed heading deg (optional)","number")
      field("verticalFov","Calibrated vertical FOV (optional)","number")
      field("headingValidated","Rotating heading verified","boolean")
    else
      for _,key in ipairs({"gravity","muzzleVelocity","minYaw","maxYaw","minPitch","maxPitch","yawSign","pitchSign","yawOffset","pitchOffset"}) do field(key,key,"number") end
      field("validated","Geometry/ballistics physically calibrated","boolean")
    end
    return rows
  end
  local function actions()
    if app.page=="radar" or app.page=="three" then return {{id="rescan",label="Rescan"},{id="autoRadars",label="Auto setup"},{id="overview",label=app.view.network and "Local view" or "Overview"},{id="radarNext",label="Radar"},{id="radarConfig",label="Setup"},{id="alias",label="Alias"},{id="radarProbe",label="Read/Probe"},{id="zoomIn",label="Zoom+"},{id="zoomOut",label="Zoom-"},{id="left",label="Rotate-"},{id="right",label="Rotate+"},{id="up",label="Tilt+"},{id="down",label="Tilt-"}}
    elseif app.page=="network" then local net=radarNet.configuration() return {{id="networkToggle",label=net.enabled and "Network ON" or "Network OFF"},{id="publishToggle",label=net.publish and "Station ON" or "Station OFF"},{id="networkConfig",label="Zone/Group"},{id="networkRescan",label="Discover"},{id="previous",label="Up"},{id="next",label="Down"}}
    elseif app.page=="targets" then return {{id="alias",label="Alias"},{id="previous",label="Up"},{id="next",label="Down"}}
    elseif app.page=="cannons" then return {{id="rescan",label="Rescan"},{id="ack",label="Verify/acknowledge"},{id="previous",label="Up"},{id="next",label="Down"}}
    elseif app.page=="fire" then return {{id="solve",label="Solve"},{id="aim",label="Aim once"},{id="track",label=app.tracking and "Stop track" or "Track"},{id="fire",label="Fire"}}
    elseif app.page=="probe" then return {{id="probe",label="Read/export"},{id="rescan",label="Rescan"},{id="previous",label="Up"},{id="next",label="Down"}}
    elseif app.configKind=="network" then return {{id="networkSave",label="Save"},{id="networkCancel",label="Cancel"}}
    else return {{id="configKind",label="Radar/Cannon"},{id="save",label="Save"},{id="rescan",label="Rescan"}} end
  end
  function app:draw(w,h)
    if self.setup then self.setup:draw(w,h) return end
    if h<9 then renderer.writeAt(1,1,renderer.crop("Combat: enlarge window",w)) return end
    local title="Combat"
    for _,tab in ipairs(tabs) do if tab.id==self.page then title=tab.label end end
    menus.bar(self.pages,1,1,w,tabs,{selector=true,label="Views: "..title,title="Combat views",selected=self.page})
    local commands=actions()
    for _,command in ipairs(commands) do
      command.primary=command.id=="overview" or command.id=="radarConfig" or command.id=="zoomIn" or command.id=="zoomOut" or command.id=="solve" or command.id=="aim" or command.id=="fire" or command.id=="save" or command.id=="probe" or command.id=="alias" or command.id=="networkToggle" or command.id=="networkRescan" or command.id=="networkSave" or command.id=="networkCancel" or command.id=="rescan"
      command.danger=command.id=="fire"
    end
    self.bar=menus.bar(self.commands,1,2,w,commands,{title=title.." actions"})
    self.rowHits={}
    local snap=self.snapshot
    if self.page=="radar" or self.page=="three" or self.page=="targets" then
      local counts={} for _,target in ipairs(snap.targets or {}) do local category=filter.category(target) counts[category]=(counts[category] or 0)+1 end
      local buttons={{id="all",label=(next(self.filters)==nil and "[x] " or "[ ] ").."All"}}
      for _,category in ipairs(filter.categories) do buttons[#buttons+1]={id=category.id,label=(self.filters[category.id] and "[x] " or "[ ] ")..category.label.." "..(counts[category.id] or 0)} end
      local selected={}
      for _,category in ipairs(filter.categories) do if self.filters[category.id] then selected[#selected+1]=category.label end end
      menus.bar(self.categories,1,4,w,buttons,{selector=true,label="Show: "..(#selected==0 and "All contacts" or table.concat(selected,", ")),title="Contact filters",keepOpen=true})
    else self.filterBar=nil self.categories.open=false self.categories.trigger=nil end
    if self.page=="radar" or self.page=="three" then
      self.view.three=self.page=="three"
      self.view.filters=self.filters
      local panel=w>=75 and 27 or 0
      local graphW,graphH=w-panel,math.max(2,h-6)
      local key=table.concat({snap.revision or 0,graphW,graphH,tostring(self.targetId),tostring(self.radarId),self.page,self.view.zoom,self.view.yaw,self.view.pitch},":")
      if not self.canvas or self.graphW~=graphW or self.graphH~=graphH or (key~=self.graphKey and os.clock()-(self.graphAt or -1)>=0.05) then
        self.canvas,self.graphHits,self.labels,self.graphStatus=instruments.radar(graphW,graphH,snap,self.radarId,self.targetId,self.view)
        self.graphW,self.graphH,self.graphKey,self.graphAt=graphW,graphH,key,os.clock()
        self.labelLayout=nil
      end
      renderer.writeAt(1,3,renderer.crop((self.graphStatus or "").." | "..tostring(self.radarId or "No radar"),w),colors.cyan)
      if snap.ok==false and snap.errors and snap.errors[1] then renderer.writeAt(1,3,renderer.crop("Read error: "..snap.errors[1],w),colors.orange) end
      self.canvas:draw(1,5)
      local radar=find(snap.radars,self.radarId)
      if radar and (not radar.position or not radar.range or radar.range<=0) then
        local p=radar.rawPosition
        local rows={"Radar: "..radar.name,radar.readStatus or "Waiting for readings",
          "Contacts returned: "..tostring(radar.rawTrackCount or "unavailable"),
          "Raw position: "..(p and (fmt(p.x)..", "..fmt(p.y)..", "..fmt(p.z)) or "unavailable"),
