        local rows=target and {target.label,"Name source: "..target.labelSource,"Distance "..fmt(relative and relative.distance).."m","Bearing "..fmt(relative and relative.bearing).."deg","Altitude "..fmt(target.position.y).."m","Age "..fmt(os.clock()-target.timestamp).."s",target.stale and "STALE - control blocked" or "", "Cone: "..tostring(radar and radar.fovSource or "unknown")} or {"No selection","Radars: "..#(snap.radars or {}),"Contacts: "..#filter.targets(snap.targets,self.filters),"Display target: 20 Hz","Zone: "..(snap.zone and snap.zone.alerts and "ON" or "OFF"),"Cone: "..tostring(radar and radar.fovSource or "unknown"),"Position: "..tostring(radar and radar.positionSource or "unavailable")}
        if target then rows[#rows+1]="Type: "..filter.category(target) rows[#rows+1]=target.remote and "Remote: display only" or "Local measurement" end
        if snap.acquisition then
          rows[#rows+1]="Read target 5 Hz; measured "..fmt(snap.acquisition.effectiveHz).." Hz"
          rows[#rows+1]="Pending "..snap.acquisition.pending.."; cycle "..fmt(snap.acquisition.elapsed).."s"
        end
        if radar then
          rows[#rows+1]="Heading: "..fmt(radar.heading).." deg"
          rows[#rows+1]="FOV: "..fmt(radar.fov).." deg"
          rows[#rows+1]="Range: "..fmt(radar.range).." m"
          rows[#rows+1]="Scan: "..(radar.running==nil and "unknown" or radar.running and "RUNNING" or "STOPPED")
          if radar.scanHeadingFrame=="body" and not radar.heading then rows[#rows+1]="Body heading not converted" end
        end
        for i=1,math.min(#rows,h-6) do renderer.writeAt(x,4+i,renderer.crop(rows[i],panel-2)) end
      end
    elseif self.page=="network" then
      local network=radarNet.snapshot()
      renderer.writeAt(1,3,renderer.crop(network.error or ((network.modem or "No modem").." | "..radarNet.configuration().group.." | ID "..os.getComputerID()),w),colors.cyan)
      renderer.writeAt(1,4,renderer.crop("Stations (tap to include/exclude)",w))
      self.scroll=math.max(1,math.min(self.scroll,math.max(1,#network.nodes-(h-7)+1)))
      for i=self.scroll,math.min(#network.nodes,self.scroll+h-8) do
        local row=network.nodes[i] local y=5+i-self.scroll
        renderer.writeAt(1,y,renderer.crop((row.included and "[x] " or "[ ] ")..row.label.." #"..row.id.." | "..(row.online and (row.radars.." radars / "..row.targets.." contacts") or "OFFLINE"),w),row.online and colors.white or colors.gray)
        self.rowHits[#self.rowHits+1]={id=row.id,x=1,y=y,w=w,h=1}
      end
      if #network.nodes==0 then renderer.writeAt(1,5,renderer.crop("No station discovered",w),colors.orange) end
      renderer.writeAt(1,h-1,renderer.crop("Rednet: unencrypted; no remote weapon commands",w),colors.orange)
    elseif self.page=="targets" or self.page=="cannons" or self.page=="probe" then
      local rows=self.page=="targets" and filter.targets(snap.targets,self.filters) or self.page=="cannons" and snap.cannons or snap.devices
      local listHeight=self.page=="probe" and math.max(1,math.floor((h-5)/3)) or h-(self.page=="targets" and 6 or 5)
      self.scroll=math.max(1,math.min(self.scroll,math.max(1,#rows-listHeight+1)))
      for i=self.scroll,math.min(#rows,self.scroll+listHeight-1) do
        local row=rows[i] local y=(self.page=="targets" and 5 or 4)+i-self.scroll
        local badge=row.synthetic and " SYNTHETIC" or row.friendly and " FRIENDLY" or ""
        local label=self.page=="targets" and (row.label..badge.." | y="..fmt(row.position.y)..(row.stale and " STALE" or "")) or self.page=="cannons" and (row.name.." | yaw="..fmt(row.yaw).." pitch="..fmt(row.pitch).." assembled="..tostring(row.assembled)) or (row.name.." "..row.role)
        local selected=self.page=="targets" and self.targetId or self.page=="cannons" and self.cannonId or self.deviceId
        renderer.writeAt(1,y,renderer.crop(label,w),row.id==selected and colors.yellow or colors.white,row.id==selected and colors.gray or nil)
        self.rowHits[#self.rowHits+1]={id=row.id,x=1,y=y,w=w,h=1}
      end
      if #rows==0 then renderer.writeAt(1,self.page=="targets" and 5 or 4,renderer.crop("No visible contacts/peripherals",w),colors.orange) end
      if self.page=="probe" then
        local selected=find(rows,self.deviceId)
        local y=5+listHeight
        renderer.writeAt(1,y,renderer.crop("Methods: "..table.concat(selected and selected.methods or {},", "),w),colors.cyan)
        local probe=snap.probe
        if probe and probe.name==self.deviceId then
          local values={}
          for key,value in pairs(probe.values or {}) do values[#values+1]=key.." = "..textutils.serialize(value):gsub("\n"," ") end
          for key,value in pairs(probe.errors or {}) do values[#values+1]=key.." ERROR "..value end
          table.sort(values)
          for i=1,math.min(#values,h-y-1) do renderer.writeAt(1,y+i,renderer.crop(values[i],w)) end
        end
      end
    elseif self.page=="fire" then
      local target=find(snap.targets,self.targetId)
      local rows={"Cannon: "..tostring(self.cannonId or "select in Cannons"),"Target: "..tostring(target and target.label or "select in Targets"),"Track: "..(self.tracking and "2 Hz" or "OFF"),"Fire: independent, single-use confirmation"}
      if self.solution then rows[#rows+1]="Yaw "..fmt(self.solution.yaw).." Pitch "..fmt(self.solution.pitch) rows[#rows+1]="ESTIMATE: vacuum trajectory, no drag" end
      for i=1,math.min(#rows,h-5) do renderer.writeAt(1,3+i,renderer.crop(rows[i],w)) end
    else
      renderer.writeAt(1,3,renderer.crop(self.configKind..": "..tostring(self.configKind=="radar" and self.radarId or self.configKind=="alias" and self.targetId or self.cannonId or "none"),w),colors.cyan)
      self.form:draw(w,h,fields())
    end
    renderer.writeAt(1,h,renderer.crop(self.message,w),colors.white,colors.gray)
    if self.confirm then
      renderer.fill(1,3,w,h-3,colors.gray)
      renderer.writeAt(1,4,renderer.crop(self.confirm.title,w),colors.white,colors.gray)
      self.confirmBar=ui.toolbar(1,6,w,{{id="confirm",label="Confirm"},{id="cancel",label="Cancel"}})
    end
    if not self.confirm and not self.form.edit then menus.overlay(self.pages,w,h) menus.overlay(self.commands,w,h) menus.overlay(self.categories,w,h) end
  end
  function app:handle(event)
    if self.setup then
      self.setup:handle(event)
      if self.setup.closed then
        if self.setup.saved then self.radarId=self.setup.id cfg=combat.configuration() self.page="radar" end
        self.setup=nil
      end
      return true
    end
    if self.confirm then
      if event.name=="mouse_click" then
        local id=ui.toolbarHit(self.confirmBar,event.args[2],event.args[3])
        if id=="confirm" then local callback=self.confirm.callback self.confirm=nil callback()
        elseif id=="cancel" then self.confirm=nil end
      end return true
    end
    if self.form.edit then return self.form:handle(event) end
    local section,command,handled=menus.route({{name="pages",state=self.pages},{name="commands",state=self.commands},{name="categories",state=self.categories}},event)
    if handled then
      if section=="pages" then
        if command then self.page=command self.scroll=1 self.tracking=false self.canvas=nil end
        return true
      elseif section=="categories" then
        if command then
          filter.toggle(self.filters,command) self.canvas=nil self.scroll=1
          local target=find(self.snapshot.targets,self.targetId)
          if target and not filter.visible(target,self.filters) then selectTarget(self.targetId) end
        end
        return true
      end
      if not command then return true end
    end
    if event.name=="mouse_scroll" and self.page~="config" then self.scroll=self.scroll+event.args[1] return true end
    if event.name~="mouse_click" and not command then return self.page=="config" and self.form:handle(event) or false end
    local _,x,y=table.unpack(event.args)
    local id=command
    if id=="networkToggle" or id=="publishToggle" then
      local value=radarNet.configuration() local key=id=="networkToggle" and "enabled" or "publish"
      value[key]=not value[key] if key=="publish" and value.publish then value.enabled=true end
      report(radarNet.configure(actor,value)) return true
    elseif id=="networkRescan" then radarNet.rescan() return true
    elseif id=="networkConfig" then self.networkConfig=radarNet.configuration() self.configKind="network" self.page="config" self.form.scroll=1 self.barState.first=1 return true
    elseif id=="networkSave" then
      local ok,message=radarNet.configure(actor,self.networkConfig) report(ok,message)
      if ok then self.page="network" self.configKind="radar" self.barState.first=1 end return true
    elseif id=="networkCancel" then self.page="network" self.configKind="radar" self.barState.first=1 return true
    elseif id=="overview" then self.view.network=not self.view.network self.canvas=nil self.view.zoom=1 return true end
    if id=="rescan" then combat.rescan() return true
    elseif id=="autoRadars" then
      confirm("Use automatic scanner API for all local radars?",function() report(combat.autoConfigureRadars(actor)) self.canvas=nil end) return true
    elseif id=="radarConfig" then
      local radar=find(self.snapshot.radars,self.radarId)
      if radar and radar.remote then self.message="Configure this radar on its source station" return true end
      self.tracking=false
      self.setup=radarSetup.new(self.snapshot,self.radarId,combat.configuration(),require("system.services.sabled").status().inSublevel,
        function(radarId,value) return combat.configure(actor,"radars",radarId,value) end,combat.validateRadar)
      return true
    elseif id=="radarProbe" then
      local radar=find(self.snapshot.radars,self.radarId)
      if radar and radar.remote then self.message="Probe runs on the source station" return true end
      self.deviceId=self.radarId self.page="probe" self.scroll=1 self.barState.first=1
      if self.deviceId then report(combat.requestProbe(actor,self.deviceId)) end return true
    elseif id=="zoomIn" or id=="zoomOut" then self.view.zoom=math.max(0.25,math.min(16,self.view.zoom*(id=="zoomIn" and 1.5 or 1/1.5))) self.canvas=nil return true
    elseif id=="left" or id=="right" then self.view.yaw=(self.view.yaw+(id=="right" and 15 or -15))%360 self.canvas=nil return true
    elseif id=="up" or id=="down" then self.view.pitch=math.max(-80,math.min(80,self.view.pitch+(id=="up" and 10 or -10))) self.canvas=nil return true
    elseif id=="radarNext" then
      local index=1 for i,row in ipairs(self.snapshot.radars) do if row.id==self.radarId then index=i break end end
      if #self.snapshot.radars>0 then self.radarId=self.snapshot.radars[index%#self.snapshot.radars+1].id self.canvas=nil end return true
    elseif id=="previous" or id=="next" then self.scroll=math.max(1,self.scroll+(id=="next" and 1 or -1)) return true
    elseif id=="solve" then solve() return true
    elseif id=="aim" then report(combat.requestAim(actor,self.cannonId,self.targetId)) return true
    elseif id=="track" then
      if self.tracking then self.tracking=false else solve() self.tracking=self.solution~=nil end return true
    elseif id=="fire" then
      self.tracking=false
      local cannonId,targetId=self.cannonId,self.targetId
      local token,err=combat.prepareFire(actor,cannonId,targetId)
      if not token then self.message=err return true end
      confirm("Fire "..cannonId.." -> "..targetId:sub(1,12).."? (5s)",function() report(combat.requestFire(actor,cannonId,targetId,token)) end) return true
    elseif id=="ack" then local cannonId=self.cannonId confirm("Physically verify stopped mount/output",function() report(combat.acknowledge(actor,cannonId,true)) end) return true
    elseif id=="probe" then report(combat.requestProbe(actor,self.deviceId)) return true
    elseif id=="alias" then
      if self.targetId then self.configKind="alias" self.alias={value=cfg.aliases[self.targetId] or ""} self.page="config" self.form.scroll=1 end return true
    elseif id=="configKind" then self.configKind=self.configKind=="radar" and "cannon" or "radar" self.form.scroll=1 return true
    elseif id=="save" then
      local object=configObject()
      if not object then self.message="Select a device first" return true end
      local section=self.configKind=="radar" and "radars" or self.configKind=="alias" and "aliases" or "profiles"
      local targetId=self.configKind=="radar" and self.radarId or self.configKind=="alias" and self.targetId or self.cannonId
      local value=addon.copy(self.configKind=="alias" and object.value or object)
      confirm("Save verified "..self.configKind.." calibration?",function() report(combat.configure(actor,section,targetId,value)) end) return true
    end
    for _,box in ipairs(self.rowHits or {}) do if ui.hit(box,x,y) then
      if self.page=="network" then
        local value=radarNet.configuration() local key=tostring(box.id)
        if value.trusted[key] then value.trusted[key]=nil report(radarNet.configure(actor,value))
        else confirm("Include station #"..key.."? Same world/dimension required",function() value.trusted[key]=true report(radarNet.configure(actor,value)) end) end
      elseif self.page=="targets" or self.page=="radar" or self.page=="three" then selectTarget(box.id)
      elseif self.page=="cannons" then self.cannonId=box.id self.tracking=false else self.deviceId=box.id end return true
    end end
    if self.page=="radar" or self.page=="three" then
      for _,box in ipairs(self.graphHits or {}) do if ui.hit({x=math.max(1,box.x-1),y=box.y+3,w=box.w,h=box.h},x,y) then selectTarget(box.id) return true end end
    end
    return self.page=="config" and self.form:handle(event) or false
  end
  refresh()
  local w,h=term.getSize()
  win=ctx.windowManager:create({title="Combat",w=math.min(120,w-2),h=math.min(38,h-2),x=2,y=2,app=app})
  ctx.onCleanup(function() if timer then os.cancelTimer(timer) end if trackTimer then os.cancelTimer(trackTimer) end combat.release(ctx.pid) end)
  timer=ctx.startTimer(0.05) trackTimer=ctx.startTimer(0.5)
  while not win.closed do
    local event=ctx.pullEvent()
    if event.name=="timer" and event.args[1]==timer then
      if not win.minimized then refresh() end
      timer=ctx.startTimer(win.minimized and 1 or (app.page=="radar" or app.page=="three") and 0.05 or 0.2)
    elseif event.name=="timer" and event.args[1]==trackTimer then
      if app.tracking and not win.minimized and not app.confirm then
        local ok,err=combat.requestAim(actor,app.cannonId,app.targetId)
        if not ok then app.tracking=false app.message=tostring(err) end
      end trackTimer=ctx.startTimer(0.5)
    elseif event.name=="mintcraft_combat_result" and event.args[1]==ctx.pid then
      report(event.args[3],event.args[4])
      if ctx.invalidate then ctx.invalidate() end
      if not event.args[3] then app.tracking=false end
    end
  end
end
return M
]=],
  ["apps/crafttube/app.cfg"] = [=[
{
  id = "crafttube",
  name = "CraftTube",
  version = "0.18.15",
  main = "apps.crafttube.main",
  permissions = { "network.http", "filesystem.read", "filesystem.write" },
}
]=],
  ["apps/crafttube/main.lua"] = [=[
local renderer = require("system.gui.renderer")
local keyboard = require("system.gui.keyboard")
local ui = require("system.gui.components")
local config = require("system.libraries.config")
local httpClient = require("system.network.http_client")
local audiod = require("system.services.audiod")
local appWorker = require("system.libraries.app_worker")

local M = {}

local cfgPath = "/system/config/crafttube.cfg"
local dataPath = "/home/user/config/crafttube.db"
local normalizeVideo

local defaultCfg = {
  provider = "invidious",
  proxy = "https://inv.thepixora.com",
  searchPath = "/api/v1/search?type=video&q=",
  detailsPath = "/api/v1/videos/",
  audioProxy = "http://127.0.0.1:8787",
  audioPath = "/crafttube/audio?id=",
  fallbackProxies = {
    "https://yt.chocolatemoo53.com",
    "https://invidious.f5.si",
  },
}

local function urlEncode(text)
  text = tostring(text or "")
  text = text:gsub("\n", "\r\n")
  text = text:gsub("([^%w%-%_%.%~ ])", function(ch)
    return string.format("%%%02X", string.byte(ch))
  end)
  return text:gsub(" ", "+")
end

local function loadCfg()
  local cfg = config.load(cfgPath, {})
  if type(cfg)~="table" then cfg={} end
  for key, value in pairs(defaultCfg) do
    if type(cfg[key])~=type(value) or cfg[key] == "" then cfg[key] = value end
  end
  return cfg
end

local function saveCfg(cfg)
  return config.save(cfgPath, cfg)
end

local function loadData()
  local data=config.load(dataPath, { favorites = {}, history = {} })
  if type(data)~="table" then data={} end
  for _,key in ipairs({"favorites","history"}) do
    local rows={}
    if type(data[key])=="table" then
      for i=1,math.min(30,#data[key]) do
        local row=data[key][i]
        if type(row)=="table" and type(row.id)=="string" and type(row.title)=="string" then rows[#rows+1]=normalizeVideo(row) end
      end
    end
    data[key]=rows
  end
  return data
end

local function saveData(data)
  return config.save(dataPath, data)
end

normalizeVideo = function(raw)
  if type(raw) ~= "table" then return nil end
  local id = raw.id
  local snippet=type(raw.snippet)=="table" and raw.snippet or {}
  if type(id) == "table" then id = id.videoId or id.id end
  id = raw.videoId or raw.video_id or id
  local title = raw.title or raw.name or snippet.title
  if not id and raw.url then id = tostring(raw.url):match("[?&]v=([%w%-_]+)") or tostring(raw.url):match("youtu%.be/([%w%-_]+)") end
  if not title or title == "" then title = id or "Untitled" end
  local duration = raw.duration or raw.length or raw.lengthText
  if not duration and raw.lengthSeconds then
    local seconds = tonumber(raw.lengthSeconds) or 0
    if seconds~=seconds or seconds==math.huge or seconds==-math.huge then seconds=0 end
    seconds=math.max(0,math.min(86400,math.floor(seconds)))
    duration = string.format("%d:%02d", math.floor(seconds / 60), seconds % 60)
  end
  return {
    id = tostring(id or title),
    title = tostring(title),
    channel = tostring(raw.channel or raw.channelTitle or raw.author or snippet.channelTitle or "-"),
    description = tostring(raw.description or snippet.description or ""),
    duration = tostring(duration or "-"),
    views = tostring(raw.viewCountText or raw.views or raw.viewCount or "-"),
    published = tostring(raw.publishedText or raw.published or ""),
    url = tostring(raw.url or ("https://www.youtube.com/watch?v=" .. tostring(id or ""))),
  }
end

local function listFromJson(json)
  local source = type(json)=="table" and (json.items or json.results or json.videos or json)
  local out = {}
  if type(source) == "table" then
    for i=1,math.min(#source,100) do
      local item=source[i]
      local video = normalizeVideo(item)
      if video then table.insert(out, video) end
    end
  end
  return out
end

local function findById(rows, id)
  for _, item in ipairs(rows or {}) do
    if item.id == id then return item end
  end
  return nil
end

local function addUnique(list, item)
  for i = #list, 1, -1 do
    if list[i].id == item.id then table.remove(list, i) end
  end
  table.insert(list, 1, item)
  while #list > 30 do table.remove(list) end
end

local function splitLines(text, width)
  local rows = {}
  width = math.max(8, width or 40)
  for raw in tostring(text or ""):gmatch("[^\r\n]+") do
    local line = raw:gsub("%s+", " ")
    while #line > width do
      table.insert(rows, line:sub(1, width))
      line = line:sub(width + 1)
    end
    table.insert(rows, line)
  end
  if #rows == 0 then table.insert(rows, "") end
  return rows
end

function M.run(ctx)
  local app = {
    cfg = loadCfg(),
    data = loadData(),
    mode = "search",
    input = (ctx.args and ctx.args.query) or "",
    status = "Configure proxy in Settings or paste it here.",
    selected = nil,
    rows = {},
    scroll = 1,
    keyboard = {},
  }
  local worker
  local function enqueue(action)
    local cfg={}
    for key,value in pairs(app.cfg) do cfg[key]=value end
    local ok,err=worker:submit({action=action,input=app.input,cfg=cfg,video=findById(app.rows,app.selected)})
    app.status=ok and "Loading..." or tostring(err)
  end

  local actions = {
    { id = "search", label = "Search" },
    { id = "play", label = "Play" },
    { id = "proxy", label = "Proxy" },
    { id = "audio", label = "Audio" },
    { id = "fav", label = "Fav" },
    { id = "history", label = "History" },
    { id = "details", label = "Details" },
  }

  local function selectedVideo()
    return findById(app.rows, app.selected)
  end

  local function replaceSelected(video)
    for i, item in ipairs(app.rows) do
      if item.id == video.id then
        app.rows[i] = video
        return
      end
    end
  end

  local function showRows(rows, status)
    app.rows = rows or {}
    app.scroll = 1
    app.selected = app.rows[1] and app.rows[1].id or nil
    app.status = status or tostring(#app.rows) .. " results"
  end

  local function searchWithProxy(proxy,request)
    if type(proxy)~="string" then return nil,"Invalid proxy" end
    local url = proxy .. request.cfg.searchPath .. urlEncode(request.input)
    local allowed, denied = ctx.security.require("network.http", url)
    if not allowed then return nil, denied end
    local response, err = httpClient.json(url,{timeout=5,maxBytes=1048576})
    if not response then return nil, err end
    return listFromJson(response.json)
  end

  local function search(request)
    if request.input == "" then app.status = "Enter search text" return end
    local proxies = { request.cfg.proxy }
    for i=1,math.min(4,#request.cfg.fallbackProxies) do table.insert(proxies,request.cfg.fallbackProxies[i]) end
    app.status = "Searching..."
    local lastErr
    for _, proxy in ipairs(proxies) do
      local rows, err = searchWithProxy(proxy,request)
      if rows and #rows > 0 then
        if app.cfg.proxy==request.cfg.proxy then app.cfg.proxy = proxy saveCfg(app.cfg) end
        showRows(rows, "Search complete via " .. proxy)
        return
      end
      lastErr = err or "no results"
    end
    app.status = tostring(lastErr or "no results")
  end

  local function toggleFavorite()
    local video = selectedVideo()
    if not video then app.status = "No video selected" return end
    addUnique(app.data.favorites, video)
    saveData(app.data)
    app.status = "Favorite saved"
  end

  local function openVideo(request)
    local video = request.video
    if not video then app.status = "No video selected" return end
    if request.cfg.proxy ~= "" and request.cfg.detailsPath ~= "" then
      local detailsUrl = request.cfg.proxy .. request.cfg.detailsPath .. urlEncode(video.id)
      local allowed,denied = ctx.security.require("network.http", detailsUrl)
      if not allowed then app.status=tostring(denied) return end
      local response,err = httpClient.json(detailsUrl,{timeout=8,maxBytes=1048576})
      if not response then app.status=tostring(err) return end
      if response and type(response.json)=="table" then
        local detail = normalizeVideo(response.json.video or response.json.item or response.json)
        if detail then
          video = detail
          replaceSelected(video)
        end
      end
    end
    addUnique(app.data.history, video)
    saveData(app.data)
    app.status = "Opened details"
  end

  local function playSelected(request)
    local video = request.video
    if not video then app.status = "No video selected" return end
    if request.cfg.audioProxy == "" then
      app.status = "Start DFPWM proxy on http://127.0.0.1:8787"
      return
    end
    local base = request.cfg.audioProxy:gsub("/+$", "")
    local audioPath = request.cfg.audioPath
    local url = base .. audioPath .. urlEncode(video.id)
    local allowed, denied = ctx.security.require("network.http", url)
    if not allowed then app.status = denied return end
    app.status = "Downloading DFPWM audio..."
    local response, err = httpClient.get(url, { binary = true,maxBytes=4194304,timeout=125 })
    if not response then app.status = tostring(err) return end
    if not fs.exists("/var/tmp") then fs.makeDir("/var/tmp") end
    local path = "/var/tmp/crafttube_audio_"..tostring(ctx.pid)..".dfpwm"
    local handle = fs.open(path, "wb")
    if not handle then app.status = "Cannot write audio temp file" return end
    local wrote,writeErr=pcall(handle.write,response.body)
    pcall(handle.close)
    if not wrote then app.status=tostring(writeErr) return end
    local ok, playErr = audiod.playDfPWM(path)
    app.status = ok and ("Playing " .. video.title) or tostring(playErr)
  end

  local function saveProxy()
    if app.input ~= "" then
      if app.mode == "audio" then
        app.cfg.audioProxy = app.input:gsub("/+$", "")
        app.cfg.audioPath = app.cfg.audioPath or defaultCfg.audioPath
      else
        app.cfg.proxy = app.input:gsub("/+$", "")
        app.cfg.searchPath = app.cfg.searchPath or defaultCfg.searchPath
        app.cfg.detailsPath = app.cfg.detailsPath or defaultCfg.detailsPath
      end
      saveCfg(app.cfg)
      app.status = app.mode == "audio" and "Audio proxy saved" or "Proxy saved"
    end
  end

  app.keyboard.onText = function(ch) app.input = app.input .. ch end
  app.keyboard.onBackspace = function() app.input = app.input:sub(1, -2) end
  app.keyboard.onEnter = function()
    if app.mode == "proxy" or app.mode == "audio" then saveProxy() else enqueue("search") end
  end

  function app:draw(w, h)
    self.toolbar = ui.toolbar(1, 1, w, actions)
    local kbH = keyboard.height()
    local selected = selectedVideo()
    local inputLabel = self.mode == "proxy" and "Proxy" or (self.mode == "audio" and "Audio proxy" or "Search")
    ui.input(1, 2, w, inputLabel, self.input, true)
    renderer.writeAt(1, 3, renderer.crop("Status: " .. self.status, w), colors.black, colors.lightGray)
    local cardH = 3
    local listH = math.max(1, h - kbH - 10)
    local visible = math.max(1, math.floor(listH / cardH))
    for i = 1, visible do
      local item = self.rows[self.scroll + i - 1]
      local y = 4 + (i - 1) * cardH
      if item then
        local bg = item.id == self.selected and colors.cyan or colors.lightGray
        renderer.writeAt(1, y, renderer.crop("[" .. tostring(self.scroll + i - 1) .. "] " .. item.title, w), colors.black, bg)
        renderer.writeAt(1, y + 1, renderer.crop("    " .. item.channel .. "   " .. item.duration .. "   " .. item.views, w), colors.gray, colors.lightGray)
        renderer.writeAt(1, y + 2, renderer.crop("    " .. item.url, w), colors.gray, colors.lightGray)
      else
        renderer.writeAt(1, y, renderer.crop("No result. Set a proxy, then search.", w), colors.gray, colors.lightGray)
      end
    end
    local detailY = 4 + visible * cardH
    if selected then
      renderer.writeAt(1, detailY, renderer.crop("Selected: " .. selected.title, w), colors.white, colors.gray)
      renderer.writeAt(1, detailY + 1, renderer.crop(selected.channel .. "  " .. selected.duration .. "  " .. selected.views .. "  " .. selected.published, w), colors.black, colors.lightGray)
      local lines = splitLines(selected.description, w)
      renderer.writeAt(1, detailY + 2, renderer.crop(lines[1] or "", w), colors.gray, colors.lightGray)
      renderer.writeAt(1, detailY + 3, renderer.crop("Play requires DFPWM proxy: " .. tostring(self.cfg.audioProxy or "-"), w), colors.gray, colors.lightGray)
    else
      renderer.writeAt(1, detailY, renderer.crop("CraftTube is the YouTube app for MintCraft OS.", w), colors.white, colors.gray)
      renderer.writeAt(1, detailY + 1, renderer.crop("It needs a proxy/API because CC:Tweaked cannot run YouTube web UI.", w), colors.gray, colors.lightGray)
      renderer.writeAt(1, detailY + 2, renderer.crop("Default API: " .. tostring(self.cfg.proxy), w), colors.gray, colors.lightGray)
    end
    self.keyboard.x = 1
    self.keyboard.y = h - kbH + 1
    self.keyboard.hint = self.mode == "proxy" and "Proxy URL" or (self.mode == "audio" and "DFPWM audio proxy URL" or "Search")
    keyboard.draw(1, self.keyboard.y, w, self.keyboard)
  end

  function app:handle(event)
    if event.name == "mouse_scroll" then
      self.scroll = math.max(1, self.scroll + event.args[1])
      return true
    elseif event.name == "char" then
      self.input = self.input .. event.args[1]
      return true
    elseif event.name == "key" then
      local key = event.args[1]
      if key == keys.backspace then self.input = self.input:sub(1, -2) return true end
      if key == keys.enter then self.keyboard.onEnter() return true end
    elseif event.name == "mouse_click" then
      local _, x, y = table.unpack(event.args)
      if event.monitorTouch and keyboard.handle(event, self.keyboard) then return true end
      local action = ui.toolbarHit(self.toolbar, x, y)
      if action == "search" then self.mode = "search" enqueue("search") return true end
      if action == "play" then enqueue("play") return true end
      if action == "proxy" then self.mode = "proxy" self.input = self.cfg.proxy or "" return true end
      if action == "audio" then self.mode = "audio" self.input = self.cfg.audioProxy or "" return true end
      if action == "fav" then toggleFavorite() return true end
      if action == "history" then showRows(self.data.history, "History") return true end
      if action == "details" then
        local video = selectedVideo()
        if video then enqueue("details") end
        return true
      end
      if y >= 4 then
        local item = self.rows[self.scroll + math.floor((y - 4) / 3)]
        if item then self.selected = item.id enqueue("details") return true end
      end
    end
    return false
  end

  showRows(app.data.favorites, "Favorites")
  local sw, sh = term.getSize()
  local win = ctx.windowManager:create({ title = "CraftTube", w = math.min(78, sw - 4), h = math.min(24, sh - 3), x = 4, y = 3, app = app })
  worker=appWorker.new(ctx,"CraftTube requests",function(request)
    if request.action=="search" then search(request)
    elseif request.action=="details" then openVideo(request)
    elseif request.action=="play" then playSelected(request) end
  end,function(_,ok,err)
    if not ok then app.status=tostring(err) end
  end,140)
  ctx.onCleanup(function()
    local path="/var/tmp/crafttube_audio_"..tostring(ctx.pid)..".dfpwm"
    if fs.exists(path) then pcall(fs.delete,path) end
  end)
  if app.input~="" then enqueue("search") end
  while not win.closed do ctx.pullEvent() end
end

return M
