local config = require("system.libraries.config")
local safeWrite = require("system.libraries.safe_write")

local M = {
  path = "/system/security/users.db",
}

local function computerId()
  if os.getComputerID then return os.getComputerID() end
  if os.computerID then return os.computerID() end
  return 0
end

-- Only used to authenticate existing installations during migration.
local function legacyHash(password)
  password = tostring(password or "")
  local h = 5381 + computerId()
  for i = 1, #password do
    h = ((h * 33) + string.byte(password, i)) % 2147483647
  end
  return tostring(h)
end

local function defaults()
  return {
    currentUser = "admin",
    locked = false,
    users = {
      admin = {
        name = "admin",
        role = "admin",
        passwordHash = legacyHash(""),
        permissions = { "*" },
      },
      guest = {
        name = "guest",
        role = "guest",
        passwordHash = legacyHash(""),
        permissions = {
          "filesystem.read",
          "network.http",
          "rednet.send",
          "rednet.receive",
          "logs.read",
          "devices.list",
          "sable.read",
          "avionics.read",
          "combat.read",
          "peripheral.probe",
        },
      },
    },
    roles = {
      admin = { "*" },
      guest = {
        "filesystem.read",
        "network.http",
        "rednet.send",
        "rednet.receive",
        "logs.read",
        "devices.list",
        "sable.read",
        "avionics.read",
        "combat.read",
        "peripheral.probe",
      },
    },
  }
end

local function mergeDefaults(db)
  local def = defaults()
