  if M.ctx and M.ctx.eventBus then
    for _, id in ipairs(M.listeners) do M.ctx.eventBus:off(id) end
  end
  M.listeners = {}
  M.ctx = nil
  M.ready = false
end

function M.status()
  local st = speaker.status()
  st.ready = M.ready
  st.playing = M.stream ~= nil
  return st
end

function M.test()
  return speaker.test()
end

function M.notify(level)
